Signed-off-by: Ren Wei <n05ec@lzu.edu.cn>
Reviewed-by: Simon Horman <horms@kernel.org>
Signed-off-by: Steffen Klassert <steffen.klassert@secunet.com>

Here is the root cause:
In xfrm6_rcv_encap(), when ip6_route_input_lookup() returns a dst entry with dst->error set, the code jumps to the drop label without releasing the reference on that dst entry, causing a memory leak of dst entries.

Here is the patch:

 int xfrm6_rcv_encap(struct sk_buff *skb, int nexthdr, __be32 spi,
 		    int encap_type)
 {
 	int ret;
 	struct xfrm6_protocol *handler;
 	struct xfrm6_protocol __rcu **head = proto_handlers(nexthdr);

 	XFRM_TUNNEL_SKB_CB(skb)->tunnel.ip6 = NULL;
 	XFRM_SPI_SKB_CB(skb)->family = AF_INET6;
 	XFRM_SPI_SKB_CB(skb)->daddroff = offsetof(struct ipv6hdr, daddr);

 	if (!head)
 		goto out;

 	if (!skb_dst(skb)) {
 		const struct ipv6hdr *ip6h = ipv6_hdr(skb);
 		int flags = RT6_LOOKUP_F_HAS_SADDR;
 		struct dst_entry *dst;
 		struct flowi6 fl6 = {
 			.flowi6_iif   = skb->dev->ifindex,
 			.daddr        = ip6h->daddr,
 			.saddr        = ip6h->saddr,
 			.flowlabel    = ip6_flowinfo(ip6h),
 			.flowi6_mark  = skb->mark,
 			.flowi6_proto = ip6h->nexthdr,
 		};

 		dst = ip6_route_input_lookup(dev_net(skb->dev), skb->dev, &fl6,
 					     skb, flags);
-		if (dst->error)
+		if (dst->error) {
+			dst_release(dst);
 			goto drop;
+		}
 		skb_dst_set(skb, dst);
 	}

 	for_each_protocol_rcu(*head, handler)
 		if ((ret = handler->input_handler(skb, nexthdr, spi, encap_type)) != -EINVAL)
 			return ret;

 out:
 	icmpv6_send(skb, ICMPV6_DEST_UNREACH, ICMPV6_PORT_UNREACH, 0);

 drop:
 	kfree_skb(skb);
 	return 0;
 }
 EXPORT_SYMBOL(xfrm6_rcv_encap);


